package com.kilivana.backend.ecommerce.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Request to create an order from a checkout quote.
 *
 * <p>This endpoint accepts a quote ID instead of line items and delivery fee directly.
 * The quote was previously generated by POST /api/v1/checkout/delivery-quote and contains
 * all the order details. The server validates the quote, recalculates prices, and creates the order.
 */
@Schema(description = "Checkout order creation request")
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class CheckoutOrderRequest {

    @Schema(description = "Quote ID from delivery-quote endpoint", example = "opaque-id")
    @NotBlank(message = "Quote ID is required")
    private String quoteId;

    @Schema(description = "Phone number for M-PESA STK Push (optional, if different from user's registered phone)", example = "254712345678")
    private String phoneNumber;
}
